// Minimal reader for `kicad-cli sch export netlist --format kicadxml` output: components (ref,
// value, footprint, fields, symbol UUIDs) and nets (name, nodes). The format is generated by
// eeschema's NETLIST_EXPORTER_XML; only the parts the gates compare are read.

export interface NetlistComponent {
  ref: string;
  value: string;
  footprint: string;
  fields: Record<string, string>;
  /** <property name value> entries, e.g. dnp, exclude_from_bom (value may be empty). */
  properties: Record<string, string>;
  /** Symbol UUIDs of the placed units on the component's sheet (KiCad lists a multi-unit part once, on the first
   *  sheet that holds one of its units, with the UUIDs of the units on that sheet only). */
  tstamps: string[];
  /** The component's sheet: names like "/" or "/Power supply/", tstamps like "/" or "/<sheetUuid>/". */
  sheetpath: { names: string; tstamps: string };
}

export interface NetlistNet {
  name: string;
  nodes: { ref: string; pin: string; pintype: string }[];
}

const decode = (s: string) =>
  s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, "&");

function attrs(tag: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const m of tag.matchAll(/([A-Za-z_:][\w:.-]*)="([^"]*)"/g)) out[m[1]!] = decode(m[2]!);
  return out;
}

const inner = (xml: string, name: string) => {
  const m = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`).exec(xml);
  return m ? decode(m[1]!.trim()) : "";
};

function sheetpathOf(body: string): NetlistComponent["sheetpath"] {
  const m = /<sheetpath\b([^>]*)\/>/.exec(body);
  const a = m ? attrs(m[1]!) : {};
  return { names: a.names ?? "", tstamps: a.tstamps ?? "" };
}

/** The board footprint's path for a component, as Update PCB from Schematic (F8) sets it: the sheet path's UUIDs
 *  and the first UUID of `tstamps` (pcbnew's BOARD_NETLIST_UPDATER), "/<symbol>" on the root sheet and
 *  "/<sheet>/<symbol>" on a page. */
export const footprintPath = (c: Pick<NetlistComponent, "sheetpath" | "tstamps">) => `${c.sheetpath.tstamps || "/"}${c.tstamps[0] ?? ""}`;

export function parseNetlistXml(xml: string): { components: NetlistComponent[]; nets: NetlistNet[] } {
  if (!/<export\b/.test(xml)) throw new Error("not a KiCad XML netlist (no <export> element)");
  const components: NetlistComponent[] = [];
  for (const m of xml.matchAll(/<comp\b([^>]*)>([\s\S]*?)<\/comp>/g)) {
    const body = m[2]!;
    const fields: Record<string, string> = {};
    for (const f of body.matchAll(/<field\b([^>]*?)(?:\/>|>([\s\S]*?)<\/field>)/g)) fields[attrs(f[1]!).name ?? ""] = decode((f[2] ?? "").trim());
    const properties: Record<string, string> = {};
    for (const p of body.matchAll(/<property\b([^>]*)\/>/g)) {
      const a = attrs(p[1]!);
      if (a.name !== undefined) properties[a.name] = a.value ?? "";
    }
    components.push({
      ref: attrs(m[1]!).ref ?? "",
      properties,
      value: inner(body, "value"),
      footprint: inner(body, "footprint"),
      fields,
      tstamps: inner(body, "tstamps").split(/\s+/).filter(Boolean),
      sheetpath: sheetpathOf(body),
    });
  }
  const nets: NetlistNet[] = [];
  for (const m of xml.matchAll(/<net\b([^>]*)>([\s\S]*?)<\/net>/g)) {
    nets.push({
      name: attrs(m[1]!).name ?? "",
      nodes: [...m[2]!.matchAll(/<node\b([^>]*)\/>/g)].map((n) => {
        const a = attrs(n[1]!);
        return { ref: a.ref ?? "", pin: a.pin ?? "", pintype: a.pintype ?? "" };
      }),
    });
  }
  return { components, nets };
}
